CREATE DATABASE IF NOT EXISTS nearbyhand CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE nearbyhand;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS reported_reviews, complaints, notifications, reviews, payments, invoices, estimates, booking_status_history, bookings, customer_addresses, worker_availability, worker_services, worker_documents, workers, services, service_categories, customers, admins;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE admins (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE customers (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, mobile VARCHAR(20) NOT NULL UNIQUE, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, status ENUM('active','inactive') DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE workers (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, mobile VARCHAR(20) NOT NULL UNIQUE, email VARCHAR(190) NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, category VARCHAR(20) NOT NULL, skills TEXT, experience_years INT DEFAULT 0, address TEXT, service_area VARCHAR(150), working_hours VARCHAR(100), starting_price DECIMAL(10,2) DEFAULT 299, status ENUM('pending','approved','rejected','suspended') DEFAULT 'pending', profile_photo VARCHAR(255), profile_video VARCHAR(255) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE service_categories (id INT AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(30) UNIQUE, name VARCHAR(50), icon VARCHAR(50), active BOOLEAN DEFAULT 1);
CREATE TABLE services (id INT AUTO_INCREMENT PRIMARY KEY, category_id INT, name VARCHAR(120) NOT NULL, description TEXT, price DECIMAL(10,2) DEFAULT 299, visit_charge DECIMAL(10,2) DEFAULT 49, active BOOLEAN DEFAULT 1, FOREIGN KEY(category_id) REFERENCES service_categories(id));
CREATE TABLE worker_services (worker_id INT, service_id INT, PRIMARY KEY(worker_id,service_id), FOREIGN KEY(worker_id) REFERENCES workers(id) ON DELETE CASCADE, FOREIGN KEY(service_id) REFERENCES services(id) ON DELETE CASCADE);
CREATE TABLE worker_documents (id INT AUTO_INCREMENT PRIMARY KEY, worker_id INT, document_type VARCHAR(50), file_path VARCHAR(255), uploaded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(worker_id) REFERENCES workers(id) ON DELETE CASCADE);
CREATE TABLE worker_availability (id INT AUTO_INCREMENT PRIMARY KEY, worker_id INT, available_date DATE, start_time TIME, end_time TIME, available BOOLEAN DEFAULT 1, UNIQUE(worker_id,available_date,start_time), FOREIGN KEY(worker_id) REFERENCES workers(id) ON DELETE CASCADE);
CREATE TABLE customer_addresses (id INT AUTO_INCREMENT PRIMARY KEY, customer_id INT, label VARCHAR(30), house VARCHAR(150), area VARCHAR(150), city VARCHAR(100), state VARCHAR(100), postal_code VARCHAR(20), is_default BOOLEAN DEFAULT 0, FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE CASCADE);
CREATE TABLE bookings (id INT AUTO_INCREMENT PRIMARY KEY, booking_code VARCHAR(30) UNIQUE, customer_id INT, worker_id INT NULL, service_id INT, address_id INT NULL, problem_description TEXT, booking_date DATE, booking_time TIME, status VARCHAR(40) DEFAULT 'Pending', visit_charge DECIMAL(10,2) DEFAULT 49, service_amount DECIMAL(10,2) DEFAULT 299, total_amount DECIMAL(10,2) DEFAULT 348, payment_method VARCHAR(20) DEFAULT 'cash', payment_status VARCHAR(20) DEFAULT 'Pending', completion_otp_hash VARCHAR(255) NULL, problem_photo VARCHAR(255) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(customer_id) REFERENCES customers(id), FOREIGN KEY(worker_id) REFERENCES workers(id), FOREIGN KEY(service_id) REFERENCES services(id), FOREIGN KEY(address_id) REFERENCES customer_addresses(id));
CREATE TABLE booking_status_history (id INT AUTO_INCREMENT PRIMARY KEY, booking_id INT, status VARCHAR(40), changed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE CASCADE);
CREATE TABLE estimates (id INT AUTO_INCREMENT PRIMARY KEY, booking_id INT, labour_cost DECIMAL(10,2), parts_cost DECIMAL(10,2), additional_charges DECIMAL(10,2) DEFAULT 0, taxes DECIMAL(10,2) DEFAULT 0, total DECIMAL(10,2), description TEXT, approval_status ENUM('pending','approved','rejected') DEFAULT 'pending', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE CASCADE);
CREATE TABLE payments (id INT AUTO_INCREMENT PRIMARY KEY, booking_id INT, amount DECIMAL(10,2), method VARCHAR(20), transaction_id VARCHAR(100), status VARCHAR(20), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(booking_id) REFERENCES bookings(id));
CREATE TABLE invoices (id INT AUTO_INCREMENT PRIMARY KEY, booking_id INT UNIQUE, invoice_number VARCHAR(40) UNIQUE, amount DECIMAL(10,2), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(booking_id) REFERENCES bookings(id));
CREATE TABLE reviews (id INT AUTO_INCREMENT PRIMARY KEY, booking_id INT UNIQUE, customer_id INT, worker_id INT, rating INT CHECK(rating BETWEEN 1 AND 5), review TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(booking_id) REFERENCES bookings(id), FOREIGN KEY(customer_id) REFERENCES customers(id), FOREIGN KEY(worker_id) REFERENCES workers(id));
