CREATE TABLE notifications (id INT AUTO_INCREMENT PRIMARY KEY, user_role ENUM('customer','worker','admin') NOT NULL, user_id INT NOT NULL, message VARCHAR(255) NOT NULL, is_read BOOLEAN DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE complaints (id INT AUTO_INCREMENT PRIMARY KEY, customer_id INT, worker_id INT NULL, booking_id INT NULL, subject VARCHAR(150), message TEXT NOT NULL, status ENUM('open','reviewing','resolved') DEFAULT 'open', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(customer_id) REFERENCES customers(id), FOREIGN KEY(worker_id) REFERENCES workers(id), FOREIGN KEY(booking_id) REFERENCES bookings(id));
CREATE TABLE reported_reviews (id INT AUTO_INCREMENT PRIMARY KEY, review_id INT NOT NULL, customer_id INT NOT NULL, reason VARCHAR(255), status ENUM('open','reviewed','dismissed') DEFAULT 'open', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(review_id) REFERENCES reviews(id) ON DELETE CASCADE, FOREIGN KEY(customer_id) REFERENCES customers(id));
